	var gold_gain := 0
	for r in results:
		var rd := r as Dictionary
		var pid := String(rd.get("id", ""))
		if pid == "":
			rd["is_new"] = false
			rd["dup"] = 0
			continue
		if G.owns_pet(pid):
			var g := int(dup_cfg.get(String(rd.get("rarity", "white")), 0))
			rd["is_new"] = false
			rd["dup"] = g
