# ================= 行为逻辑 =================

func _draw_saved(mode: String) -> void:
	var outcome := G.saved_mutation(func():
		# 缺失奖池直接拒绝整单，保底不能拿低品质宠物冒充。
		for rarity in RARITY_ORDER:
			if float(_rates().get(rarity, 0.0)) > 0.0 and _pool_of(rarity).is_empty():
				return {"ok": false, "err": "奖池配置不完整，暂不能召唤"}
		if _pool_of("purple").is_empty() or _pool_of("gold").is_empty():
			return {"ok": false, "err": "保底奖池配置不完整，暂不能召唤"}
		var bonus := 0
		if mode == "free":
			if not G.gacha_free_available(): return {"ok": false, "err": "今日免费已领取 · 明日再来"}
			bonus = G.gacha_mark_free()
		elif mode == "ten" and G.item_count("ticket_ten") > 0:
			if not G.consume_item("ticket_ten", 1): return {"ok": false, "err": "十连券不可用"}
		else:
			var cost := int(_pool().get("cost_soul_ten" if mode == "ten" else "cost_soul_single", 720 if mode == "ten" else 80))
			if cost < 0 or int(G.wallet.get("soul", 0)) < cost:
				return {"ok": false, "err": "魂石不足：本次需 %d 魂石" % cost}
			G.wallet["soul"] = int(G.wallet.get("soul", 0)) - cost
		var results := _roll_batch(10 if mode == "ten" else 1)
		if results.any(func(r): return String(r.get("id", "")).is_empty()):
			return {"ok": false, "err": "奖池配置不完整，召唤已取消"}
		_settle(results)
		return {"ok": true, "results": results, "bonus": bonus})
	if not bool(outcome.get("ok", false)):
		_warn(String(outcome.get("err", "召唤未保存")))
		return
	_show_results("ten" if mode == "ten" else "single", outcome.results)
	if int(outcome.get("bonus", 0)) > 0:
		_warn("连续七日 · 魂晶 +%d" % int(outcome.bonus), Color("ffe9b8"))
	_refresh_top()


func _do_single() -> void:
	_draw_saved("single")


func _do_ten() -> void:
	_draw_saved("ten")


func _do_free() -> void:
	_draw_saved("free")


## 再抽一次：按上次模式重放
func _again() -> void:
	if _last_mode == "single":
		_do_single()
	else:
		_do_ten()


func _close() -> void:
	closed.emit()


## ESC / 返回手势关闭本浮层（轮次 14 统一口径）。
## 与结果层「返回」按钮同一条路径：召唤页的结果层是整屏接管页，没有"只收起结果层"
## 的可见操作，ESC 就照按钮的口径走，不额外发明一层。
func _unhandled_input(event: InputEvent) -> void:
	if G.ui_blocked:
		return
	if event.is_action_pressed("ui_cancel"):
		_close()
		get_viewport().set_input_as_handled()


## 行内提示：默认深红警告；传 color 可换色（如奖励的金色）；1.5 秒后淡出（重复触发重置计时）
func _warn(msg: String, color := Color(0, 0, 0, 0)) -> void:
	var target := _hint
	var col := Color("ffb6a3")
	if _result != null and _result.visible and _r_hint != null:
		target = _r_hint
		col = Color("ff9a8a")
	if color.a > 0.0:
		col = color
	if target == null:
		return
	target.text = msg
	target.add_theme_color_override("font_color", col)
	target.modulate.a = 1.0
	var old: Tween = null
	if target.has_meta("fade_tw"):
		old = target.get_meta("fade_tw") as Tween
	if old != null:
		old.kill()
	var tw := target.create_tween()
	target.set_meta("fade_tw", tw)
	tw.tween_interval(1.5)
	tw.tween_property(target, "modulate:a", 0.0, 0.45)


# ================= 抽取内核 =================

## 某稀有度的宠物池（pets.json）
func _pool_of(rarity: String) -> Array:
	var out: Array = []
	for p in TableCache.pets():
		if String((p as Dictionary).get("rarity", "")) == rarity:
			out.append(p)
	return out


func _rand_id(rng: RandomNumberGenerator, pool: Array) -> String:
	if pool.is_empty():
		return ""
	return String((pool[rng.randi_range(0, pool.size() - 1)] as Dictionary).get("id", ""))


## randf 按权重选稀有度 → 再在该稀有度宠物里随机
func _pick_pet(rng: RandomNumberGenerator, rarity: String) -> String:
	var pool := _pool_of(rarity)
	return _rand_id(rng, pool)


func _roll_rarity(rng: RandomNumberGenerator, rates: Dictionary) -> String:
	var roll := rng.randf()
	var acc := 0.0
	for k in RARITY_ORDER:
		acc += float(rates.get(k, 0.0))
		if roll < acc:
			return String(k)
	return "white"


## 保底档：按紫/金原始权重比例在两档里挑
func _roll_high(rng: RandomNumberGenerator, rates: Dictionary) -> String:
	var p := float(rates.get("purple", 0.0))
	var g := float(rates.get("gold", 0.0))
	if p + g <= 0.0:
		return "purple"
	return "purple" if rng.randf() < p / (p + g) else "gold"


## 稀有度判定钩子：满保底走紫/金池，否则按权重正常抽。
## 单独一层是为了给测试一个"只换判定、不换引擎"的缝——子类覆写它就能确定性走完每一条保底路径。
func _decide_rarity(rng: RandomNumberGenerator, rates: Dictionary, pity: int, pity_max: int) -> String:
	if pity >= pity_max:
		return _roll_high(rng, rates)
	return _roll_rarity(rng, rates)


## 抽 n 张：随机源在本层创建（局外 RNG 与战斗种子 RNG 严禁互串）。判定逻辑见 roll_batch_with。
func _roll_batch(n: int) -> Array:
	var rng := RandomNumberGenerator.new()
	rng.randomize()
	return roll_batch_with(n, rng)

extends RefCounted
## One round, one save: scores, first clear, title, side quest and materials move together.

static func state(host: Object) -> Dictionary:
	if not host.prog.get("flags") is Dictionary: host.prog["flags"] = {}
	var flags: Dictionary = host.prog.flags
	if not flags.get("archery_state") is Dictionary: flags["archery_state"] = {}
	var value: Dictionary = flags.archery_state
	for key in ["best_scores", "cleared", "first_claimed"]:
		if not value.get(key) is Dictionary: value[key] = {}
	return value

static func unlocked(host: Object, mode: Dictionary) -> bool:
	var required := String(mode.get("requires_clear", ""))
	var value: Dictionary = host.prog.get("flags", {}).get("archery_state", {})
	return required.is_empty() or bool(value.get("cleared", {}).get(required, false))

static func settle(host: Object, mode: Dictionary, token: String, score: int, bullseyes: int, lit_hits := 0) -> Dictionary:
	if host.save_locked: return {"ok": false, "line": "存档暂不可写，本局成绩已保留。请恢复保存后重试。"}
	if token.is_empty() or not unlocked(host, mode): return {"ok": false, "line": "请先完成初试百步，再参加巡灯守夜。"}
	var arrows := int(mode.get("arrows", 5))
	if score < 0 or score > arrows * 10 or bullseyes < 0 or bullseyes > arrows or lit_hits < 0 or lit_hits > arrows:
		return {"ok": false, "line": "本局成绩无效，未发放奖励。"}
	if RewardLedger.applied(host.ledger(), token): return {"ok": true, "duplicate": true, "line": "本局已保存，奖励已入袋。"}
	var before := {"prog": host.prog.duplicate(true), "wallet": host.wallet.duplicate(true), "items": host.items.duplicate(true)}
	var value := state(host)
	var id := String(mode.id)
	value.total_plays = int(value.get("total_plays", 0)) + 1
	value.total_bullseyes = int(value.get("total_bullseyes", 0)) + bullseyes
	value.best_scores[id] = maxi(int(value.best_scores.get(id, 0)), score)
	var passed := score >= int(mode.get("pass_score", 28)) and lit_hits >= int(mode.get("required_lit_hits", 0))
	var mastered := passed and score >= int(mode.get("master_score", 42))
	var grants := {}
	var parts: Array[String] = []
	var first := passed and not bool(value.first_claimed.get(id, false))
	if passed:
		value.cleared[id] = true
		value.first_claimed[id] = true
		var reward: Dictionary = mode.get("first_reward" if first else "repeat_reward", {})
		for currency in ["gold", "expedition", "soul", "honor"]:
			var count := maxi(0, int(reward.get(currency, 0)))
			if count > 0:
				grants[currency] = count
				parts.append("%s+%d" % [String({"gold": "金币", "expedition": "远征币", "soul": "魂晶", "honor": "荣誉"}[currency]), count])
		for item in reward.get("items", {}):
			var count := maxi(0, int(reward.items[item]))
			if count > 0:
				grants["item:" + String(item)] = count
				parts.append("%s×%d" % [host.item_name(String(item)), count])
		# Mastery is independent of the first-clear reward, including older saves.
		var title := String(mode.get("first_reward", {}).get("title", ""))
		if mastered and not title.is_empty():
			if not host.prog.get("titles") is Dictionary: host.prog["titles"] = {"owned": [], "active": ""}
			var titles: Dictionary = host.prog.titles
			if not titles.get("owned", []) is Array: titles["owned"] = []
			if not titles.get("owned", []).has(title):
				var owned: Array = titles.get("owned", [])
				owned.append(title)
				titles["owned"] = owned
				parts.append("解锁称号【百步穿杨】")
		if host.has_method("side_report"): host.side_report("archery", id, "lorin_wilds", false)
	var applied := RewardLedger.apply(RewardLedger.make(token, {}, grants), host.ledger(), host)
	if not bool(applied.get("ok", false)) or not host.save_game():
		host.prog = before.prog
		host.wallet = before.wallet
		host.items = before.items
		return {"ok": false, "line": "本局尚未保存，奖励未入账；点击「重试保存」即可重试。"}
	var line := "【%s】%d环 · %s：%s" % ["神射魁首" if mastered else "演武达标", score, "首通" if first else "再战", " · ".join(parts)] if passed else \
		"本局%d环，达标需%d环。%s再调整风偏与蓄力试试。" % [score, int(mode.get("pass_score", 28)), "需亮灯命中%d箭；" % int(mode.required_lit_hits) if mode.has("required_lit_hits") else ""]
	return {"ok": true, "passed": passed, "mastered": mastered, "first": first, "line": line}

